            diag: dg('줄을 긋고 있어요', '긋다', 'prog', 'wrongProg').concat([{ p: '(지금 |)(바닥에 |)줄(을|) 그어고 있어요', note: '-고 goes straight onto the stem 긋: 긋고 있어요.' }, { p: '(지금 |)(바닥에 |)줄(을|) 긋어 있어요', note: 'Present progressive = stem + -고 있어요: 긋고 있어요.' }]),
