            diag: dg('빨리 나을 거예요', '낫다', 'fut', 'wrongFut').concat([{ p: '(코코(는|) |)(곧 |빨리 |)나을 거야', note: 'Right form, but to Grandma you keep 존댓말 (Lesson 27): 나을 거예요.' }]),
